import type { Question } from '../types';

function q(
  topicId: string,
  n: number,
  prompt: string,
  options: string[],
  correctIndex: number,
  explanation: string,
): Question {
  return { id: `${topicId}-${n}`, topicId, prompt, options, correctIndex, explanation };
}

